def build():
    OUT.mkdir(parents=True,exist_ok=True)
    result=pd.DataFrame(ROWS,columns=['point','decision','critical_assessment','action','evidence'])
    assert result.point.tolist()==list(range(1,24))
    result.to_csv(OUT/'expert_dispositions.csv',index=False)
    (OUT/'expert_dispositions.json').write_text(json.dumps(result.to_dict('records'),ensure_ascii=False,indent=2))
    return result


if __name__=='__main__':build()
